import { sqlEntries } from '../../src/db/sqlLibrary';

/** Markdown for docs/sql-reference.md, generated from sql/validation-queries.sql. */
export function buildSqlReference(): string {
  const entries = sqlEntries();
  const lines: string[] = [
    '# Oracle SQL reference',
    '',
    '> Generated from [`sql/validation-queries.sql`](../sql/validation-queries.sql) by `npm run docs:sql`.',
    '> Do not edit by hand: change the `.sql` file and regenerate. `npm run docs:check` fails if this file is stale.',
    '',
    '## Schema under test',
    '',
    'One table, discovered in the repository (upstream README DDL and the JPA entity `Person`). There are no other tables, views or foreign keys.',
    '',
    '| Column | Oracle type | Nullable | Notes |',
    '|---|---|---|---|',
    '| `ID` | `INTEGER` (NUMBER) | no | identity `GENERATED BY DEFAULT`, primary key `PK_PERSON` |',
    '| `FIRST_NAME` | `VARCHAR2(255)` | no | |',
    '| `LAST_NAME` | `VARCHAR2(255)` | no | |',
    '| `BIRTH_DATE` | `DATE` | no | calendar date (JPA `LocalDate`) |',
    '',
    'Bind variables use `:name`. Result columns are aliased in camelCase (`"firstName"`) so rows compare directly with the API JSON.',
    '',
    '## Index',
    '',
    '| ID | Kind | Title | Used by |',
    '|---|---|---|---|',
    ...entries.map((e) => `| [${e.id}](#${e.id.toLowerCase()}) | ${e.kind} | ${e.title} | ${e.usedBy} |`),
    '',
    '## Entries',
    '',
  ];
  for (const e of entries) {
    lines.push(
      `### ${e.id}`,
      '',
      `**${e.title}**`,
      '',
      `- **Purpose:** ${e.purpose}`,
      `- **Expected result:** ${e.expect}`,
      `- **Schema objects:** ${e.objects}`,
      `- **Used by:** ${e.usedBy}`,
      '',
      '```sql',
      `${e.sql};`,
      '```',
      '',
    );
  }
  return lines.join('\n');
}
